import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import LoadingSpinner from '../../components/LoadingSpinner';
import toast from 'react-hot-toast';

const ROLE_REDIRECTS = {
    citizen: '/citizen/dashboard',
    police: '/police/dashboard',
    municipal: '/municipal/dashboard',
    admin: '/admin/dashboard',
};

/**
 * Intermediate page that Clerk redirects to after sign-in/sign-up.
 * AuthContext is already syncing in the background via the useEffect in AuthContext.
 * We just wait until `isAuthenticated` becomes true, then redirect by role.
 */
const ClerkCallback = () => {
    const { user, loading, isAuthenticated } = useAuth();
    const navigate = useNavigate();

    useEffect(() => {
        if (!loading && isAuthenticated && user) {
            toast.success(`Welcome, ${user.name}!`);
            navigate(ROLE_REDIRECTS[user.role] || '/', { replace: true });
        } else if (!loading && !isAuthenticated) {
            // Sync failed or user cancelled — go back to login
            navigate('/login', { replace: true });
        }
    }, [loading, isAuthenticated, user, navigate]);

    return (
        <div className="flex flex-col items-center justify-center min-h-screen gap-4">
            <LoadingSpinner fullScreen />
            <p className="text-sm text-gray-500 mt-4">Signing you in…</p>
        </div>
    );
};

export default ClerkCallback;
